+namespace Microsoft.Integration.Shopify.Test;
+
+using Microsoft.Integration.Shopify;
+using Microsoft.Sales.History;
+using System.TestLibraries.Utilities;
+
+codeunit 139614 "Shpfy Shipping 3P Test"
+{
+    Subtype = Test;
+    TestType = IntegrationTest;
+    TestPermissions = Disabled;
+    TestHttpRequestPolicy = BlockOutboundRequests;
+
+    var
+        Shop: Record "Shpfy Shop";
+        Any: Codeunit Any;
+        LibraryAssert: Codeunit "Library Assert";
+        InitializeTest: Codeunit "Shpfy Initialize Test";
+        IsInitialized: Boolean;
+
+    [Test]
+    procedure ExportShipment3rdPartyFulfillmentSkipped()
+    var
+        SalesShipmentHeader: Record "Sales Shipment Header";
+        ShopLocation: Record "Shpfy Shop Location";
+        ExportShipments: Codeunit "Shpfy Export Shipments";
+        ShippingHelper: Codeunit "Shpfy Shipping Helper";
+        DeliveryMethodType: Enum "Shpfy Delivery Method Type";
+        FulfillmentRequests: List of [Text];
+        AssignedFulfillmentOrderIds: Dictionary of [BigInteger, Code[20]];
+        ShopifyOrderId: BigInteger;
+        LocationId: BigInteger;
+    begin
+        // [SCENARIO] Fulfillment orders associated with a 3rd party fulfillment service should be skipped during shipment export
+        // [GIVEN] A sales shipment linked to a Shopify order at a location that is a 3rd party fulfillment service
+        Initialize();
+        LocationId := Any.IntegerInRange(10000, 99999);
+        DeliveryMethodType := DeliveryMethodType::Shipping;
+        ShopifyOrderId := ShippingHelper.CreateRandomShopifyOrder(LocationId, DeliveryMethodType);
+        ShippingHelper.CreateShopifyFulfillmentOrder(ShopifyOrderId, DeliveryMethodType);
+        ShippingHelper.CreateRandomSalesShipment(SalesShipmentHeader, ShopifyOrderId);
+        CreateThirdPartyFulfillmentLocation(ShopLocation, LocationId);
+
+        // [WHEN] CreateFulfillmentOrderRequest is invoked
+        FulfillmentRequests := ExportShipments.CreateFulfillmentOrderRequest(SalesShipmentHeader, Shop, LocationId, DeliveryMethodType, AssignedFulfillmentOrderIds);
+
+        // [THEN] No fulfillment requests should be created
+        LibraryAssert.AreEqual(0, FulfillmentRequests.Count, 'No fulfillment requests expected for 3rd party fulfillment service');
+    end;
+
+    [Test]
+    procedure ExportShipmentBCFulfillmentNotSkipped()
+    var
+        SalesShipmentHeader: Record "Sales Shipment Header";
+        ShopLocation: Record "Shpfy Shop Location";
+        FulfillmentOrderHeader: Record "Shpfy FulFillment Order Header";
+        ExportShipments: Codeunit "Shpfy Export Shipments";
+        ShippingHelper: Codeunit "Shpfy Shipping Helper";
+        DeliveryMethodType: Enum "Shpfy Delivery Method Type";
+        FulfillmentRequest: Text;
+        FulfillmentRequests: List of [Text];
+        AssignedFulfillmentOrderIds: Dictionary of [BigInteger, Code[20]];
+        ShopifyOrderId: BigInteger;
+        LocationId: BigInteger;
+    begin
+        // [SCENARIO] Fulfillment orders for BC's own fulfillment service should NOT be skipped during shipment export
+        // [GIVEN] A sales shipment linked to a Shopify order at a location that is BC's fulfillment service
+        Initialize();
+        LocationId := Any.IntegerInRange(10000, 99999);
+        DeliveryMethodType := DeliveryMethodType::Shipping;
+        ShopifyOrderId := ShippingHelper.CreateRandomShopifyOrder(LocationId, DeliveryMethodType);
+        FulfillmentOrderHeader := ShippingHelper.CreateShopifyFulfillmentOrder(ShopifyOrderId, DeliveryMethodType);
+        ShippingHelper.CreateRandomSalesShipment(SalesShipmentHeader, ShopifyOrderId);
+        CreateBCFulfillmentLocation(ShopLocation, LocationId);
+
+        // [WHEN] CreateFulfillmentOrderRequest is invoked
+        FulfillmentRequests := ExportShipments.CreateFulfillmentOrderRequest(SalesShipmentHeader, Shop, LocationId, DeliveryMethodType, AssignedFulfillmentOrderIds);
+
+        // [THEN] Fulfillment requests should be created (not skipped)
+        LibraryAssert.AreEqual(1, FulfillmentRequests.Count, 'Fulfillment request expected for BC fulfillment service');
+        FulfillmentRequests.Get(1, FulfillmentRequest);
+        LibraryAssert.IsTrue(FulfillmentRequest.Contains(Format(FulfillmentOrderHeader."Shopify Fulfillment Order Id")), 'Fulfillment order Id check');
+    end;
+
+    local procedure CreateThirdPartyFulfillmentLocation(var ShopLocation: Record "Shpfy Shop Location"; LocationId: BigInteger)
+    begin
+        ShopLocation.Init();
+        ShopLocation."Shop Code" := Shop.Code;
+        ShopLocation.Id := LocationId;
+        ShopLocation.Name := '3rd Party Fulfillment Svc.';
+        ShopLocation."Is Fulfillment Service" := true;
+        ShopLocation.Insert();
+    end;
+
+    local procedure CreateBCFulfillmentLocation(var ShopLocation: Record "Shpfy Shop Location"; LocationId: BigInteger)
+    var
+        SyncLocations: Codeunit "Shpfy Sync Shop Locations";
+    begin
+        ShopLocation.Init();
+        ShopLocation."Shop Code" := Shop.Code;
+        ShopLocation.Id := LocationId;
+        ShopLocation.Name := CopyStr(SyncLocations.GetFulfillmentServiceName(), 1, MaxStrLen(ShopLocation.Name));
+        ShopLocation."Is Fulfillment Service" := true;
+        ShopLocation.Insert();
+    end;
+
+    local procedure Initialize()
+    var
+        CommunicationMgt: Codeunit "Shpfy Communication Mgt.";
+        LibraryTestInitialize: Codeunit "Library - Test Initialize";
+        LibraryRandom: Codeunit "Library - Random";
+        AccessToken: SecretText;
+    begin
+        LibraryTestInitialize.OnTestInitialize(Codeunit::"Shpfy Shipping 3P Test");
+        ClearLastError();
+
+        if IsInitialized then
+            exit;
+
+        LibraryTestInitialize.OnBeforeTestSuiteInitialize(Codeunit::"Shpfy Shipping 3P Test");
+
+        LibraryRandom.Init();
+        Any.SetDefaultSeed();
+
+        IsInitialized := true;
+        Commit();
+
+        Shop := InitializeTest.CreateShop();
+        CommunicationMgt.SetTestInProgress(false);
+
+        AccessToken := LibraryRandom.RandText(20);
+        InitializeTest.RegisterAccessTokenForShop(Shop.GetStoreName(), AccessToken);
+
+        LibraryTestInitialize.OnAfterTestSuiteInitialize(Codeunit::"Shpfy Shipping 3P Test");
+    end;
+}
